import{_ as t,o as a,c as r,ak as o}from"./chunks/framework.sV-XtlWr.js";const p=JSON.parse('{"title":"Privacy & data flow","description":"Exactly what leaves your server and when, what never does, what Piwi does not capture, and how secrets are stored.","frontmatter":{"title":"Privacy & data flow","description":"Exactly what leaves your server and when, what never does, what Piwi does not capture, and how secrets are stored.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/guide/privacy.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/guide/privacy.html"}],["meta",{"property":"og:title","content":"Privacy & data flow | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Exactly what leaves your server and when, what never does, what Piwi does not capture, and how secrets are stored."}]]},"headers":[],"relativePath":"guide/privacy.md","filePath":"guide/privacy.md","lastUpdated":1790784189000}'),s={name:"guide/privacy.md"};function n(i,e,d,h,l,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="privacy-data-flow" tabindex="-1">Privacy &amp; data flow <a class="header-anchor" href="#privacy-data-flow" aria-label="Permalink to &quot;Privacy &amp; data flow&quot;">​</a></h1><p>Test results are unusually revealing: they carry your source paths, error messages, screenshots of your app, network calls, and sometimes your git history. That&#39;s a good reason to know exactly where the bytes go. This page is the inventory.</p><p>The short version: <strong>there is no telemetry</strong>, no usage analytics, no crash reporting, and no license or activation call. The server never checks for updates; the desktop app checks once at startup (turn that off in <strong>Settings → About</strong>) and when you click <strong>Check for updates</strong> there. Every outbound call the server makes is listed below, and all but two are something you switched on. An instance running on an air-gapped network works the same as one on the internet.</p><h2 id="what-leaves-your-server" tabindex="-1">What leaves your server <a class="header-anchor" href="#what-leaves-your-server" aria-label="Permalink to &quot;What leaves your server&quot;">​</a></h2><p>Every outbound connection Piwi can make:</p><table tabindex="0"><thead><tr><th>Destination</th><th>When</th><th>Carries</th></tr></thead><tbody><tr><td>Your AI provider</td><td>Only if you configure <a href="/features/ai-diagnosis.html">AI diagnosis</a></td><td>The diagnosis context: error text, failing steps, test and related source files, console and network entries, page (ARIA/DOM) snapshots, server logs, the relevant git diff, and up to five failure screenshots by default (<code>PIWI_AI_MAX_IMAGES=0</code> sends none). <a href="/features/ai-steps.html">AI-step</a> authoring sends masked page snapshots</td></tr><tr><td>Your git host</td><td>Whenever runs report a GitHub, GitLab or Bitbucket remote (the reporter records <code>origin</code> by default)</td><td>Without a token: anonymous public-API reads of the repository&#39;s default branch and its CODEOWNERS. With a token: commits, diffs and files, plus the PR comments, commit statuses, heal branches and CI re-runs of the features you turn on</td></tr><tr><td>A URL you attach as a link</td><td>When someone adds a link to a run, test or cluster</td><td>A request for its title (the git host&#39;s API for an issue or PR link)</td></tr><tr><td>Your issue tracker (Jira)</td><td>Only if you <a href="/features/issue-tracking.html">connect it</a></td><td>Issue reads, and the issues and comments you file</td></tr><tr><td>Your SMTP server</td><td>Only if you configure <a href="/features/notifications.html">email notifications</a></td><td>Notification and account emails</td></tr><tr><td>Your Slack / webhook URLs</td><td>Only for subscriptions you create</td><td>The event payload (run status, cluster, test names, file paths, short error excerpts)</td></tr><tr><td>Your S3 endpoint</td><td>Only if you switch <a href="/operate/storage.html">storage</a> to S3</td><td>Trace files, HTML reports, attachments</td></tr><tr><td>Google / GitHub</td><td>Only if you enable <a href="/operate/authentication.html#oauth-google-github">OAuth sign-in</a></td><td>The standard OAuth exchange</td></tr></tbody></table><p>The reporter sends your own instance what its options switch on. <a href="/features/code-reach.html">Code reach</a>, off by default, sends repository-relative file paths only: never source code, coverage counts or line numbers.</p><p>Two rows need no setting: the anonymous git-host reads happen whenever runs report a public-host remote, and a link&#39;s title is fetched when someone attaches it. Both fail quietly without network access. Everything else is off until you configure it.</p><p>The <strong>AI provider</strong> is the one worth pausing on, because it&#39;s the only destination that receives your source code and the full failure context. It&#39;s opt-in, it goes only to the endpoint <em>you</em> set — including a local model over Ollama or vLLM, in which case nothing leaves the machine at all — you can preview the exact context before it&#39;s sent, and you can cap its size. See <a href="/features/ai-diagnosis.html#privacy">AI diagnosis → Privacy</a>.</p><h2 id="what-never-leaves-your-server" tabindex="-1">What never leaves your server <a class="header-anchor" href="#what-never-leaves-your-server" aria-label="Permalink to &quot;What never leaves your server&quot;">​</a></h2><ul><li><strong>Traces.</strong> The Playwright trace viewer is bundled and served by your own instance at <code>/trace-viewer/</code>. Opening a trace from Piwi never uploads it anywhere — unlike sending a colleague to the hosted <code>trace.playwright.dev</code>.</li><li><strong>The API reference.</strong> <code>/docs</code> is rendered in-app from your instance&#39;s own OpenAPI spec, with no third-party CDN, so it works offline.</li><li><strong>Screenshots, videos, HTML reports.</strong> Stored on your disk or your S3 bucket, served by your instance.</li><li><strong>HTML report execution.</strong> Reports run with scripts enabled inside a CSP sandbox with a unique opaque origin. Piwi provides the report with an in-memory Web Storage facade so Playwright&#39;s settings UI works; it is discarded with the report document and cannot read the dashboard&#39;s cookies or local storage. Uploaded reports remain untrusted active content.</li><li><strong>Your IDE mapping.</strong> The <a href="/features/ide-integration.html">Open in IDE</a> workspace root lives in your browser&#39;s local storage, because the source is on your machine, not the server&#39;s. It is never sent to the dashboard.</li></ul><h2 id="what-reaches-your-server-from-piwi-picker" tabindex="-1">What reaches your server from Piwi Picker <a class="header-anchor" href="#what-reaches-your-server-from-piwi-picker" aria-label="Permalink to &quot;What reaches your server from Piwi Picker&quot;">​</a></h2><p>The <a href="/features/extension.html">browser extension</a> works with no instance. Connected, it reads a project&#39;s URL patterns, function catalog and locator index, and sends one thing: a <a href="/features/bug-reports.html">bug report</a>, only when someone clicks <strong>Send</strong> in its preview, which shows exactly what goes. That report carries the recorded steps with the values typed (never a password, and none at all with <strong>Leave out the values I typed</strong>), and whichever evidence the reporter kept ticked: screenshots of the tab, console errors and warnings, failed requests (method, path without query values, status; never a header or a body) and an outline of the page. It goes only to the instance the extension is connected to, and it is stored there like a run&#39;s evidence.</p><p><strong>Share result</strong>, after a replay of a report from the instance, sends the verdict, the site it ran on and the browser&#39;s name to that report, on <strong>Send</strong> in its preview.</p><p>Paired with the <a href="/features/bug-reports.html#running-it-with-playwright-in-the-desktop-app">desktop app</a>, it also sends a report&#39;s title and steps, with their typed values and nothing else, to that app on this machine when someone clicks <strong>Send</strong> in the <strong>Run with Playwright</strong> preview.</p><h2 id="what-piwi-deliberately-does-not-capture" tabindex="-1">What Piwi deliberately does not capture <a class="header-anchor" href="#what-piwi-deliberately-does-not-capture" aria-label="Permalink to &quot;What Piwi deliberately does not capture&quot;">​</a></h2><p>Some data is skipped at the source, so it never exists to leak:</p><ul><li><strong>Input values in locator snapshots.</strong> The <a href="./capture-fixtures.html">capture fixtures</a> record what an element <em>is</em> — role, accessible name, test id — never what was typed into it. Playwright&#39;s own records are different: step titles and parameters, traces and the failure-time ARIA snapshot include the values a test typed, password fields too, so don&#39;t fill real secrets in tests.</li><li><strong>Page-inventory field contents.</strong> The optional <a href="./reporter.html#configuration-options">page inventory</a> (<code>capturePageInventory</code>, <strong>off by default</strong>) records the names of a page&#39;s controls and links so the dashboard can tell which the suite never exercises. The name of a control that holds user input — a textbox, <code>select</code>, <code>textarea</code> or contenteditable editor — is never read from its content, so a recovery code, a draft, or a set of options never leaves the browser; link hrefs are stripped of their query and hash, which can carry signed tokens.</li><li><strong>Storage and cookie values.</strong> Page state records the <em>names</em> of <code>localStorage</code> /<code>sessionStorage</code> keys and their value lengths, and cookie names with their flags. Never the values.</li><li><strong>Sensitive headers.</strong> <code>Authorization</code>, <code>Cookie</code> and friends are masked server-side in Piwi&#39;s trace network view, and token-shaped strings in URLs and bodies are masked too. The trace file itself is stored as uploaded, so the bundled trace viewer and a downloaded trace still show them.</li><li><strong>Backend logs, in production.</strong> The <a href="./backend-logs.html">backend-log integrations</a> emit their header only in development and test environments by default.</li></ul><h2 id="secrets-at-rest" tabindex="-1">Secrets at rest <a class="header-anchor" href="#secrets-at-rest" aria-label="Permalink to &quot;Secrets at rest&quot;">​</a></h2><p>Credentials you store in the dashboard — AI API keys, SCM tokens, webhook signing secrets — are encrypted with AES-256-GCM using <code>PIWI_SECRET_KEY</code>. <strong>Set it in production.</strong> With the variable unset, or set to the development default published in this repository, the dashboard refuses to save a credential and says which variable to set. Generate a key with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;console.log(require(&#39;node:crypto&#39;).randomBytes(32).toString(&#39;hex&#39;))&quot;</span></span></code></pre></div><p>API keys are stored as SHA-256 hashes and shown exactly once, at creation. A leaked database gives an attacker no usable key.</p><p>Secrets provided by environment variable are never written to the database and never returned by the API — the settings UI shows them as read-only with a lock badge.</p><h2 id="the-demo" tabindex="-1">The demo <a class="header-anchor" href="#the-demo" aria-label="Permalink to &quot;The demo&quot;">​</a></h2><p>The <a href="https://piwitests.dev/demo/" target="_blank" rel="noreferrer">live demo</a> has no backend. It runs the real application against an in-browser SQLite database seeded with fake data, inside a service worker. Nothing you click there reaches a server, and there is nothing for it to collect.</p><h2 id="retention" tabindex="-1">Retention <a class="header-anchor" href="#retention" aria-label="Permalink to &quot;Retention&quot;">​</a></h2><p>Data you keep is data you&#39;re responsible for. Piwi can prune it for you: set <code>PIWI_RETENTION_DAYS</code> for nightly automatic pruning of old runs and their files, or delete in bulk from <strong>Settings → Storage</strong>. Deleting a run removes its executions, traces, reports, and any evidence payloads no longer referenced by anything else. See <a href="/operate/storage.html#data-retention">Storage → Data retention</a>.</p><h2 id="verifying-any-of-this" tabindex="-1">Verifying any of this <a class="header-anchor" href="#verifying-any-of-this" aria-label="Permalink to &quot;Verifying any of this&quot;">​</a></h2><p>You don&#39;t have to take the page&#39;s word for it. The source is public and the outbound surface is small enough to audit: watch the container&#39;s egress, or read <a href="https://github.com/PiwiTests/platform/tree/main/apps/application/server/utils" target="_blank" rel="noreferrer"><code>server/utils/</code></a> — the AI provider, SCM, SMTP, notification, OAuth, Jira and link-unfurl clients are the only things there that open a socket; the S3 client is in <code>server/storage/</code>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/operate/authentication.html">Authentication</a>, <a href="/operate/api-keys.html">API keys</a> and <a href="/operate/project-access.html">Project access</a>: roles, keys and project-level access</li><li><a href="/operate/production-checklist.html#before-you-expose-it">Production checklist</a> — hardening a public instance</li><li><a href="./comparison.html#is-my-data-safe-does-piwi-phone-home">Why Piwi?</a> — the same question, short form</li></ul>',31)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
